import net.minecraft.world.item.*;import net.minecraft.world.item.alchemy.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.core.*;import org.millenaire.common.goal.*;import org.millenaire.common.entity.*;import org.millenaire.common.village.*;import org.millenaire.common.utilities.*;
public class BrewingGoalCheck{
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
 net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();
 var uf=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");uf.setAccessible(true);var unsafe=(sun.misc.Unsafe)uf.get(null);
 var v=new MillVillager();v.level=(net.minecraft.server.level.ServerLevel)unsafe.allocateInstance(net.minecraft.server.level.ServerLevel.class);v.house=new Building();v.dest=new Point();v.dest.stand=new BrewingStandBlockEntity(BlockPos.ZERO,Blocks.BREWING_STAND.defaultBlockState());v.house.res.brewingStands.add(v.dest);var stand=v.dest.stand;var goal=new GoalBrewPotions();
 v.house.stock.put(Items.GLASS_BOTTLE,3);v.house.stock.put(Items.NETHER_WART,1);v.house.stock.put(Items.BLAZE_POWDER,1);v.house.rejectTake=true;goal.performAction(v);check(stand.isEmpty(),"Failed withdrawals cannot create ingredients");v.house.rejectTake=false;check(goal.getDestination(v)!=null,"Stock makes stand eligible");goal.performAction(v);
 for(int i=0;i<3;i++)check(PotionUtils.getPotion(stand.getItem(i))==Potions.WATER,"Water NBT");check(stand.getItem(3).is(Items.NETHER_WART)&&stand.getItem(4).is(Items.BLAZE_POWDER),"Ingredient and fuel slots");check(v.house.countGoods(Items.GLASS_BOTTLE)==0&&v.house.countGoods(Items.NETHER_WART)==0&&v.house.countGoods(Items.BLAZE_POWDER)==0,"Inputs consumed once");
 var finished=PotionUtils.setPotion(new ItemStack(Items.POTION),Potions.AWKWARD);finished.setHoverName(new net.minecraft.network.chat.TextComponent("keep-name"));stand.setItem(0,finished);v.house.rejectStore=true;goal.performAction(v);check(!stand.getItem(0).isEmpty()&&v.house.stored.isEmpty(),"Full storage keeps finished potion");v.house.rejectStore=false;goal.performAction(v);check(stand.getItem(0).isEmpty()&&v.house.stored.size()==1&&ItemStack.tagMatches(finished,v.house.stored.get(0)),"Finished potion tags preserved");goal.performAction(v);check(v.house.stored.size()==1,"No duplicate output");
 var tag=stand.saveWithoutMetadata();tag.putShort("BrewTime",(short)50);stand.load(tag);stand.setItem(0,finished.copy());goal.performAction(v);check(!stand.getItem(0).isEmpty()&&v.house.stored.size()==1,"Active brewing untouched");v.dest=null;check(goal.performAction(v),"Missing destination safe");v.house=null;check(goal.getDestination(v)==null,"Missing house safe");
 System.out.println("PASS: actual brewing goal + vanilla brewing stand with world/storage fixtures: stock failures, water NBT, fuel, exact consumption, full storage, tag preservation, repeat prevention, active brew and missing targets. Live server brewing tick/AI untested.");}}
